package com.voltflow.controller;
import com.voltflow.entity.ChargingStation; import com.voltflow.service.StationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/stations") @RequiredArgsConstructor
public class StationController { private final StationService service; @GetMapping List<ChargingStation> list(@RequestParam(required=false)String q){return service.list(q);} @GetMapping("/{id}") ChargingStation get(@PathVariable Long id){return service.get(id);} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','OPERATOR')") ResponseEntity<ChargingStation> create(@Valid @RequestBody ChargingStation s){return ResponseEntity.status(HttpStatus.CREATED).body(service.save(s));} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','OPERATOR')") ChargingStation update(@PathVariable Long id,@Valid @RequestBody ChargingStation s){return service.update(id,s);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){service.delete(id);} }
